from pathlib import Path
import sys

paths=[Path(p) for p in sys.argv[1:]] or [Path('/tmp/a2-pwa/www/app.html')]
if not paths[0].exists() and not sys.argv[1:]:
    paths=[Path('www/app.html')]

decode=lambda x:x.replace('§',chr(96)).replace('¤',chr(36))

PRIOR=decode(r'''function priorClosingBalance(m,month){const manual=m?.manualCarryByMonth||{};if(Object.prototype.hasOwnProperty.call(manual,month))return Number(manual[month]||0);const prev=closingDoc(previousMonthKey(month));if(prev&&Array.isArray(prev.members)){const r=prev.members.find(x=>String(x.memberId||'')===String(m.id||'')||String(x.uid||'')===String(m.uid||''));if(r)return Number(r.closingBalance||0)}if(String(m.carryToMonth||'')===String(month))return Number(m.carryBalance||0);return 0}''')

HELPERS=decode(r'''
function paymentSortTime(x){try{return Number(x?.createdAt?.toMillis?.()||x?.updatedAt?.toMillis?.()||x?.createdAt?.seconds*1000||x?.updatedAt?.seconds*1000||0)}catch{return 0}}
function paymentDateLabel(x){try{const d=x?.createdAt?.toDate?.()||x?.updatedAt?.toDate?.();return d?d.toLocaleDateString('en-GB'):'Date not recorded'}catch{return'Date not recorded'}}
window.movePaymentMonth=n=>{const d=new Date((window._paymentMonth||currentBillingMonth())+'-01T00:00:00');d.setMonth(d.getMonth()+n);window._paymentMonth=§¤{d.getFullYear()}-¤{String(d.getMonth()+1).padStart(2,'0')}§;render()};
window.openCarryAdjustment=(memberId,month)=>{if(state.profile?.role!=='admin')return toast('Admin only');const m=state.data.members.find(x=>String(x.id)===String(memberId));if(!m)return toast('Member not found');const value=priorClosingBalance(m,month),kind=value<0?'DUE':'ADVANCE';modal(§<div class=top><div><h3 style="margin:0">Carry Forward Adjustment</h3><div class=small>¤{esc(m.name)} · ¤{month}</div></div><button class=ghost onclick=closeM()>✕</button></div><div class=form style="margin-top:14px"><div class=field><label>Carry Type</label><select id=carryKind><option value=ADVANCE ¤{kind==='ADVANCE'?'selected':''}>Advance (+)</option><option value=DUE ¤{kind==='DUE'?'selected':''}>Due (−)</option></select></div><div class=field><label>Amount</label><input id=carryAmount type=number min=0 step=.01 value="¤{money(Math.abs(value))}"></div><div class="span2 note">Use this once for older balances that were recorded before month-wise carry forward was available. Automatic month-closing carry remains the default when no manual adjustment exists.</div><div class=span2><button class=btn onclick="saveCarryAdjustment('¤{esc(m.id)}','¤{month}')">SAVE CARRY FORWARD</button></div></div>§)};
window.saveCarryAdjustment=async(memberId,month)=>{if(state.profile?.role!=='admin')return toast('Admin only');const kind=¤('carryKind').value,amount=Math.max(0,Number(¤('carryAmount').value||0)),value=kind==='DUE'?-amount:amount;try{await updateDoc(doc(db,'members',memberId),{['manualCarryByMonth.'+month]:value,updatedAt:serverTimestamp()});closeM();toast(month+' carry forward saved · '+(value>=0?'Advance ':'Due ')+'AED '+money(amount))}catch(e){err(e)}};
''')

PAYMENTS=decode(r'''function payments(){const month=window._paymentMonth||currentBillingMonth(),isMember=state.profile.role==='member',self=isMember?linkedMember(auth.currentUser.uid):null,history=(isMember?state.data.payments.filter(x=>String(x.uid||'')===String(auth.currentUser.uid)):state.data.payments).filter(x=>paymentMonth(x)===month).sort((a,b)=>paymentSortTime(b)-paymentSortTime(a)),monthNav=§<div class=ref-month><button class=ghost onclick="movePaymentMonth(-1)">‹</button><b>¤{month}</b><button class=ghost onclick="movePaymentMonth(1)">›</button></div>§;if(isMember){const q=self?memberSummary(self,month):{plan:0,paid:0,opening:0,due:0,advance:0,status:'DUE'};return§¤{monthNav}<div class=grid>¤{metric('Plan','AED '+money(q.plan))}¤{metric('Paid This Month','AED '+money(q.paid))}¤{metric('Carry Forward',(q.opening>=0?'+ ':'− ')+'AED '+money(Math.abs(q.opening)))}¤{metric(q.advance>0?'Advance':'Due','AED '+money(q.advance>0?q.advance:q.due))}¤{metric('Status',q.status)}</div><div class=card style="margin-top:12px"><h3>Payment History</h3><div class=list><div class=row><span><b>Date / Member</b></span><span><b>Amount / Method</b></span><span><b>Status</b></span><span></span></div>¤{history.length?history.map(x=>§<div class=row><span><b>¤{paymentDateLabel(x)}</b><small class=muted> · ¤{esc(x.name||self?.name||'Member')}</small></span><span>AED ¤{money(paidValue(x))}<br><small class=muted>¤{cashCardMethod(x,'payment')}</small></span><span>¤{esc(x.status||'Recorded')}</span><span></span></div>§).join(''):'<p class=muted>No payment recorded for this month yet.</p>'}</div></div>§}const summaries=state.data.members.map(m=>({m,q:memberSummary(m,month)}));return§¤{monthNav}<div class=top style="margin-top:14px"><div><p class=muted style="margin:0">Payments · ¤{month}</p><div class=small>Carry forward and payments are shown for the selected month.</div></div><button class=btn onclick=paymentForm({billingMonth:'¤{month}'})>+ Payment / Advance</button></div><div class=card style="margin-top:12px"><h3>Member Balances</h3><div class=list>¤{summaries.map(({m,q})=>§<div class=row><span><b>¤{esc(m.name)}</b><small class=muted> · Plan AED ¤{money(q.plan)}</small></span><span>Paid AED ¤{money(q.paid)}<br><small class=muted>Carry ¤{q.opening>=0?'+':'−'} AED ¤{money(Math.abs(q.opening))}</small><br><small class=muted>¤{q.advance>0?'Advance AED '+money(q.advance):'Due AED '+money(q.due)}</small></span><span class="tag ¤{q.status==='DUE'?'due':q.status==='PARTIAL'?'partial':'paid'}">¤{q.status}</span><span><div class=actions><button class=ghost onclick="paymentForm({uid:'¤{memberKey(m)}',billingMonth:'¤{month}'})">Add Payment</button><button class=ghost onclick="openCarryAdjustment('¤{m.id}','¤{month}')">Carry Forward</button><button class=ghost onclick="waDue('¤{esc(m.phone||'')}','¤{esc(m.name||'Member')}','¤{month}',¤{q.plan},¤{q.paid},¤{q.opening},¤{q.due},¤{q.advance})">WhatsApp</button></div></span></div>§).join('')}</div></div><div class=card style="margin-top:12px"><h3>¤{month} Payment History · Newest First</h3><div class=list><div class=row><span><b>Date / Member</b></span><span><b>Amount / Method</b></span><span><b>Status</b></span><span><b>Actions</b></span></div>¤{history.length?history.map(x=>{const m=linkedMember(x.uid);return§<div class=row><span><b>¤{paymentDateLabel(x)}</b><small class=muted> · ¤{esc(x.name||m?.name||'Member')}</small></span><span>AED ¤{money(paidValue(x))}<br><small class=muted>¤{cashCardMethod(x,'payment')}</small></span><span>¤{esc(x.status||'Recorded')}</span><span><div class=actions><button class=ghost onclick="paymentFormById('¤{x.id}')">Edit</button><button class="ghost danger" onclick="deletePayment('¤{x.id}')">Delete</button></div></span></div>§}).join(''):'<p class=muted>No payments recorded this month.</p>'}</div></div>§}''')

def replace_between(s,start,end,replacement):
    a=s.find(start); b=s.find(end,a)
    if a<0 or b<0: raise SystemExit(f'Markers missing: {start} / {end}')
    return s[:a]+replacement+s[b:]

for app in paths:
    if not app.exists(): raise SystemExit(f'App file not found: {app}')
    s=app.read_text()
    s=replace_between(s,'function priorClosingBalance(', '\nfunction closingPreview(',PRIOR)
    s=replace_between(s,'function payments(){', '\nwindow.paymentFormForMember=',HELPERS+'\n'+PAYMENTS)
    s=s.replace("window.paymentFormForMember=uid=>paymentForm({uid,billingMonth:currentBillingMonth()});","window.paymentFormForMember=uid=>paymentForm({uid,billingMonth:window._paymentMonth||currentBillingMonth()});")
    required=['manualCarryByMonth','movePaymentMonth','Payment History · Newest First','Date / Member','Amount / Method','openCarryAdjustment','SAVE CARRY FORWARD','window._paymentMonth||currentBillingMonth()']
    missing=[x for x in required if x not in s]
    if missing: raise SystemExit('Payment month/order/carry adjustment missing: '+', '.join(missing))
    app.write_text(s)
    print('Added payment month navigation, ordering and carry adjustment:',app)
